  rev(g, o, .3, .85, 0, -ph, () => { boxes.forEach(b => { const w = bw - 2; tone(g, b.x, b.y, w, bh, c, 1, .88, L1); rect(g, b.x + w * .38, b.y, w * .24, bh, "rgba(255,248,230,.42)", 0, 0); ln(g, b.x + w * .38, b.y, b.x + w * .38, b.y + bh, 1, "rgba(43,42,39,.3)"); ln(g, b.x + w * .62, b.y, b.x + w * .62, b.y + bh, 1, "rgba(43,42,39,.3)"); rect(g, b.x + w * .08, b.y + bh * .66, w * .2, bh * .2, "rgba(255,255,255,.55)", 1, 1.1); if (b.tw) ln(g, b.x + w * .7, b.y + bh * .18, b.x + w * .9, b.y + bh * .18, 1.4, "rgba(43,42,39,.4)"); if (b.k === nrw - 1) poly(g, [[b.x, b.y], [b.x + w, b.y], [b.x + w + dx * .4, b.y - dy], [b.x + dx * .4, b.y - dy]], lit(c, .25), L1); }); const rs = boxes.filter(b => b.i === nc - 1); rs.forEach(b => poly(g, [[b.x + bw - 2, b.y], [b.x + bw - 2 + dx * .4, b.y - dy], [b.x + bw - 2 + dx * .4, b.y - dy + bh], [b.x + bw - 2, b.y + bh]], drk(c, .22), 1.8)); });
