def("mountain", (g, r, o) => {
  const w = o.s, np = o.peaks ?? r.int(3, 5), snow = o.snow ?? true, H = w * r.range(.34, .44), base = H / 2, col = o.red ? lit(P.red, .5) : r.pick(["#c9c3b6", "#b8b7b0", "#c2b8a6", "#b3bcbf"]);
  const cut = (pts, yS) => { const out = []; for (let i = 0; i < pts.length; i++) { out.push(pts[i]); if (i + 1 < pts.length && pts[i][1] >= yS && pts[i + 1][1] < yS) { /* crossing handled below */ } } return out; };
  const mk = (cx, hgt, wd) => { const apex = [cx + r.range(-.03, .03) * wd, base - hgt], L = [[cx - wd, base]], R = [], n = 5; for (let i = 1; i < n; i++) { const t = i / n; L.push([lerp(cx - wd, apex[0], t) + r.range(-.04, .04) * wd * (1 - t), base - hgt * Math.pow(t, .85) + r.range(-.03, .03) * hgt]); R.push([lerp(apex[0], cx + wd * r.range(.9, 1.1), 1 - t) + r.range(-.04, .04) * wd * (1 - t), base - hgt * Math.pow(t, .85) + r.range(-.03, .03) * hgt]); }
    R.reverse(); R.push([cx + wd * r.range(.95, 1.1), base]); const foot = [cx + wd * r.range(-.06, .2), base], ridge = [foot]; for (let i = 1; i < 4; i++) ridge.push([lerp(foot[0], apex[0], i / 4) + r.range(-.05, .05) * wd * (1 - i / 4), lerp(base, apex[1], i / 4) + r.range(-.02, .02) * hgt]); ridge.push(apex); return { apex, L, R, ridge, hgt, wd, cx }; };
  const peaks = [], bk = [], n1 = np + 1;
  for (let i = 0; i < n1; i++) { const cx = -w * .48 + w * .96 * (i + .5 + r.range(-.25, .25)) / n1, hg = H * r.range(.5, .7) * (1 - Math.abs((i + .5) / n1 - .5) * .5); bk.push(mk(cx, hg, hg * r.range(.8, 1.1))); }
  for (let i = 0; i < np; i++) { const cx = -w * .44 + w * .88 * (i + .5 + r.range(-.28, .28)) / np, hg = H * r.range(.58, 1) * (1 - Math.abs((i + .5) / np - .5) * .55); peaks.push(mk(cx, hg, hg * r.range(.75, 1.05))); }
  const full = pk => [...pk.L, pk.apex, ...pk.R];
  const draw = (pk, cc, sn, hatch) => { const poly1 = full(pk); poly(g, poly1, cc, 2.2);
    const shade = [pk.apex, ...pk.R, ...pk.ridge.slice(0, -1)]; g.save(); path(g, poly1); g.clip(); path(g, shade); g.fillStyle = drk(cc, .17); g.fill(); if (hatch) { g.save(); path(g, shade); g.clip(); g.strokeStyle = "rgba(43,42,39,.17)"; g.lineWidth = 1.2; g.beginPath(); for (let d = -pk.hgt; d < pk.wd * 2; d += 8) { g.moveTo(pk.cx + d * .5, base - pk.hgt); g.lineTo(pk.cx + d * .5 - pk.hgt * .6, base); } g.stroke(); g.restore(); } path(g, [pk.apex, ...pk.ridge.slice(0, -1)], false); ui.ink(g, 1.6, "rgba(43,42,39,.6)");
    if (sn) { const yS = pk.apex[1] + pk.hgt * .34, pts = []; const side = (arr, rev2) => { const o2 = []; for (const p of arr) if (p[1] < yS) o2.push(p); return o2; }; const Ls = pk.L.filter(p => p[1] < yS), Rs = pk.R.filter(p => p[1] < yS), z = []; const xl = Ls.length ? Ls[Ls.length - 1][0] - pk.hgt * .05 : pk.apex[0] - pk.hgt * .3, xr = Rs.length ? Rs[0][0] + pk.hgt * .05 : pk.apex[0] + pk.hgt * .3; for (let i = 0; i <= 4; i++) z.push([lerp(xr, xl, i / 4), yS + (i % 2 ? -1 : 1) * pk.hgt * .045]);
      const cap = [pk.apex, ...Rs, ...z, ...Ls.slice().reverse()]; g.save(); path(g, cap); g.fillStyle = "#fbfdfd"; g.fill(); g.save(); path(g, cap); g.clip(); path(g, [pk.apex, ...pk.R, ...pk.ridge.slice(0, -1)]); g.fillStyle = "#d3e0e7"; g.fill(); g.restore(); path(g, cap); ui.ink(g, 1.6, "rgba(43,42,39,.7)"); g.restore(); }
    g.restore(); poly(g, poly1, null, 2.2); };
  rev(g, o, 0, .5, 0, base, () => bk.forEach(pk => draw(pk, lit(col, .5), snow, false)), 1);
  rev(g, o, .3, .9, 0, base, () => peaks.slice().sort((a, b) => b.apex[1] - a.apex[1]).forEach(pk => draw(pk, col, snow, true)), 1);
  rev(g, o, .8, 1, 0, base, () => { ln(g, -w * .58, base, w * .58, base, 2.6); for (let i = 0; i < 12; i++) { const x = -w * .52 + i * w * .095 + (i % 2) * 5, hh = 7 + (i % 3) * 3; poly(g, [[x, base], [x + 5, base - hh], [x + 10, base]], lit(C.sage, .15), 1.5); } });
  const hi = peaks.slice().sort((a, b) => a.apex[1] - b.apex[1])[0];
  return { w: w * 1.2, h: H + 12, anchors: { peak: hi.apex.slice(), base: [0, base] } };
});

