  const sp = cr * 2.1, x0 = -(ns - 1) * sp / 2; const top = Math.min(...st.map(s2 => by - s2.n * th - s2.dy)) - ry; fitV(g, top - 0, by + ry + h * .04); gsh(g, 0, by + ry * .6, (ns * sp) * .56, ry * 1.1);
  st.forEach((s2, si) => rev(g, o, .05 + .55 * si / ns, .3 + .55 * si / ns, x0 + si * sp, by, () => { const cx = x0 + si * sp + s2.dx, yb = by - s2.dy * 0;
    for (let i = 0; i < s2.n; i++) { const y = yb - i * th; g.beginPath(); g.moveTo(cx - cr, y); g.lineTo(cx - cr, y - th); g.ellipse(cx, y - th, cr, ry, 0, Math.PI, 0, false); g.lineTo(cx + cr, y); g.ellipse(cx, y, cr, ry, 0, 0, Math.PI, false); g.closePath(); g.fillStyle = i % 2 ? drk(GOLD, .06) : GOLD; g.fill(); g.save(); g.clip(); g.fillStyle = drk(GOLD, .2); g.fillRect(cx + cr * .15, y - th * 2, cr, th * 3); g.fillStyle = lit(GOLD, .3); g.fillRect(cx - cr, y - th * 2, cr * .14, th * 3); g.strokeStyle = "rgba(43,42,39,.22)"; g.lineWidth = 1; g.beginPath(); for (let k = -cr; k < cr; k += cr * .12) { g.moveTo(cx + k, y - th * .85); g.lineTo(cx + k, y - th * .15); } g.stroke(); g.restore(); g.beginPath(); g.moveTo(cx - cr, y); g.lineTo(cx - cr, y - th); g.ellipse(cx, y - th, cr, ry, 0, Math.PI, 0, false); g.lineTo(cx + cr, y); g.ellipse(cx, y, cr, ry, 0, 0, Math.PI, false); g.closePath(); ui.ink(g, 1.8); }
    const ty = yb - (s2.n - 1) * th - th; ellp(g, cx, ty, cr, ry, o.red && si === Math.floor(ns / 2) ? P.red : lit(GOLD, .25), L2 * 1.2); ellp(g, cx, ty, cr * .74, ry * .72, null, 1.3); g.save(); g.translate(cx, ty); g.scale(1, ry / cr); star(g, 0, 0, cr * .38, cr * .16); g.fillStyle = o.red && si === Math.floor(ns / 2) ? P.redInk : drk(GOLD, .22); g.fill(); g.restore(); }, 1));
  rev(g, o, .7, 1, 0, by, () => { const x = x0 + (ns - 1) * sp + cr * 2.2; ellp(g, x, by + ry * .3, cr, ry, lit(GOLD, .15), L2 * 1.2); ellp(g, x, by + ry * .3, cr * .74, ry * .72, null, 1.2); const lx = x0 - cr * 2.2; g.save(); g.translate(lx, by - cr * .65); g.rotate(-.2); ellp(g, 0, 0, cr * .34, cr, GOLD, L2 * 1.2); ellp(g, 0, 0, cr * .22, cr * .72, null, 1.2); g.restore(); });
  return { w: ns * sp + cr * 5, h: -top + by * 0 + h * .5, anchors: { top: [0, top], base: [0, by], left: [x0 - cr, by] } };
